#!/usr/bin/env node
/**
 * Build every brand raster in the repo from one master SVG.
 *
 * Before this script the repo had *one* generator (the Data Uploader's) and
 * nine orphaned binaries — `favicon.ico`, the two PWA PNGs, the four browser-
 * extension PNGs and Starscape's `.ico` — with no source and no way to
 * reproduce them. That is why the products drifted onto three different marks.
 *
 * Everything now derives from `public/icons/brand/scc-mark.svg` (see
 * `scripts/brand/marks.mjs` for the family system) and is regenerated by:
 *
 *     npm run gen:brand-icons
 *
 * `--check` regenerates into memory and diffs against the working tree without
 * writing. It runs in `prebuild`, so a hand-edited or stale artifact fails the
 * build instead of shipping — the same guard `check:readme-docs` gives the docs.
 *
 * Deterministic by construction: no text is rendered (a missing font on a CI
 * host would otherwise change the bytes and make `--check` flap), and every
 * size is fixed here rather than read from the environment.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { resolve, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { Resvg } from '@resvg/resvg-js';
import pngToIco from 'png-to-ico';
import {
  deriveAppMark,
  compactMark,
  trayMark,
  monoMark,
  inlineMark,
  PRODUCTS,
  C,
} from './brand/marks.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const BRAND = resolve(ROOT, 'public/icons/brand');
const MASTER = resolve(BRAND, 'scc-mark.svg');

const CHECK = process.argv.includes('--check');

/**
 * `--only=<product>` limits output to one product's artifacts.
 *
 * The Data Uploader's CI installs only `data-uploader/node_modules`, so its
 * `package:win` chain runs this generator from the repo root for its three
 * files alone. Keeping one implementation is the point: a second renderer in
 * the uploader would drift from this one and silently ship a different icon.
 */
const ONLY = (process.argv.find((a) => a.startsWith('--only=')) ?? '').slice('--only='.length);
const want = (product) => !ONLY || ONLY === product;
if (ONLY && !PRODUCTS.includes(ONLY)) {
  console.error(`--only=${ONLY} is not a product (${PRODUCTS.join(', ')})`);
  process.exit(1);
}
const drift = [];
let written = 0;

/** Windows packs these sizes into an .ico so Explorer/taskbar/Start all match. */
const ICO_SIZES = [16, 24, 32, 48, 64, 128, 256];

function png(svg, size, { background } = {}) {
  return new Resvg(svg, {
    fitTo: { mode: 'width', value: size },
    background: background ?? 'transparent',
  })
    .render()
    .asPng();
}

/** Render at an explicit width/height — used only for the 1200x630 OG card. */
function pngBox(svg, width, height, background) {
  return new Resvg(svg, { fitTo: { mode: 'width', value: width }, background }).render().asPng();
}

function emit(absPath, buf) {
  const rel = relative(ROOT, absPath).replace(/\\/g, '/');
  if (CHECK) {
    if (!existsSync(absPath)) {
      drift.push(`${rel} — missing`);
      return;
    }
    const have = readFileSync(absPath);
    if (!have.equals(Buffer.isBuffer(buf) ? buf : Buffer.from(buf))) {
      drift.push(`${rel} — differs from the generated output`);
    }
    return;
  }
  mkdirSync(dirname(absPath), { recursive: true });
  writeFileSync(absPath, buf);
  written += 1;
  console.log(`  ${rel}`);
}

const text = (s) => Buffer.from(s, 'utf-8');

// ── 1. Sources: derive the two sibling marks + all three tiers ──────────────

if (!existsSync(MASTER)) {
  console.error(
    `missing master mark: ${relative(ROOT, MASTER)}\n` +
      'It is vendored from the SC Companion desktop app repo ' +
      '(modules/desktop/resources/app-icon-taskbar.svg). See public/icons/brand/README.md.',
  );
  process.exit(1);
}
const masterSvg = readFileSync(MASTER, 'utf-8');

console.log(CHECK ? 'checking brand sources…' : 'writing brand sources…');
const appMark = {};
for (const p of PRODUCTS) {
  appMark[p] = deriveAppMark(masterSvg, p);
  // `scc` IS the master — do not rewrite it, it is vendored, not generated.
  if (p !== 'scc') emit(resolve(BRAND, `${p}-mark.svg`), text(appMark[p]));
  emit(resolve(BRAND, `${p}-mark-compact.svg`), text(compactMark(p)));
  emit(resolve(BRAND, `${p}-mark-tray.svg`), text(trayMark(p)));
}

const compact = Object.fromEntries(PRODUCTS.map((p) => [p, compactMark(p)]));
const tray = Object.fromEntries(PRODUCTS.map((p) => [p, trayMark(p)]));

// ── 2. Web app ──────────────────────────────────────────────────────────────
//
// Small sizes take the compact tier, large sizes the full artwork: the master's
// Gaussian blurs turn to grey mush below ~64px, which is what made the old
// favicon unreadable in a browser tab.

if (want('scc')) {
console.log(CHECK ? 'checking web rasters…' : 'writing web rasters…');

emit(resolve(ROOT, 'public/favicon.ico'), await pngToIco(ICO_SIZES.map((s) => png(compact.scc, s))));

// PWA install icons. New filenames on purpose: `public/icons/` is copied
// unhashed and is not covered by any ngsw asset group, so overwriting the old
// `icon-192.png` in place would leave the CDN and every browser cache serving
// the retired mark for an unbounded time.
emit(resolve(BRAND, 'scc-192.png'), png(appMark.scc, 192));
emit(resolve(BRAND, 'scc-512.png'), png(appMark.scc, 512));

// Maskable: Android crops to a circle of ~80% diameter, so the artwork is
// inset and the canvas colour is painted edge to edge behind it.
//
// The mark is composited as an embedded raster rather than by inlining its
// markup: the master is authored in a 300-unit viewBox, so splicing its
// children into a differently-scaled parent would silently mis-size it.
const embed = (buf, x, y, w, h) =>
  `<image href="data:image/png;base64,${buf.toString('base64')}" x="${x}" y="${y}" width="${w}" height="${h}"/>`;

const maskable = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="512" height="512">
  <rect width="512" height="512" fill="${C.canvas}"/>
  ${embed(png(appMark.scc, 410), 51, 51, 410, 410)}
</svg>`;
emit(resolve(BRAND, 'scc-maskable-512.png'), png(maskable, 512, { background: C.canvas }));

// iOS Add-to-Home-Screen needs an opaque raster; it ignores SVG entirely, which
// is why `apple-touch-icon` pointed at an SVG and silently did nothing.
emit(resolve(BRAND, 'scc-apple-touch-180.png'), png(compact.scc, 180, { background: C.canvas }));

// Social preview. X and Facebook do not render SVG, so the og:image was a
// no-op; this is the raster that replaces it. No text — a font missing on a
// build host would make the bytes non-deterministic and flake `--check`.
const ogCard = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 630" width="1200" height="630">
  <defs>
    <radialGradient id="og" cx="50%" cy="46%" r="62%">
      <stop offset="0%" stop-color="#153450"/><stop offset="100%" stop-color="${C.canvas}"/>
    </radialGradient>
  </defs>
  <rect width="1200" height="630" fill="url(#og)"/>
  ${embed(png(appMark.scc, 520), 340, 55, 520, 520)}
</svg>`;
emit(resolve(BRAND, 'scc-og-1200x630.png'), pngBox(ogCard, 1200, 630, C.canvas));

emit(resolve(BRAND, 'scc-mark-mono.svg'), text(monoMark()));
}

// ── 2b. Inlined copies of the mark ──────────────────────────────────────────
//
// Two places need the mark as literal markup rather than a fetched asset. Both
// previously held a hand-written duplicate that drifted from the source. They
// are now spliced between sentinels and verified here, so the copies cannot
// silently fall behind again.

const INLINE_TARGETS = [
  ['src/index.html', 'scc', '          ', 'aria-hidden="true"'],
  // `class="logo"` is load-bearing: renderer/main.ts serialises `svg.logo` into
  // the uploader's favicon at runtime, and styles.css sizes it.
  ['data-uploader/src/renderer/index.html', 'uploader', '        ', 'class="logo" aria-hidden="true"'],
];

console.log(CHECK ? 'checking inlined marks…' : 'splicing inlined marks…');
for (const [rel, product, indent, rootAttrs] of INLINE_TARGETS) {
  if (!want(product)) continue;
  const file = resolve(ROOT, rel);
  if (!existsSync(file)) {
    drift.push(`${rel} — missing (inline mark target)`);
    continue;
  }
  // `.gitattributes` declares `eol=lf`, but a Windows checkout has CRLF in the
  // working copy. Splicing LF markup into a CRLF file leaves it mixed, and the
  // next tool that renormalises flips it back — so the check would fail on
  // whitespace alone, forever. Compare in LF; write back the file's own ending.
  const raw = readFileSync(file, 'utf-8');
  const crlf = raw.includes('\r\n');
  const src = raw.replace(/\r\n/g, '\n');
  const begin = '<!-- BRAND-MARK:BEGIN -->';
  const end = '<!-- BRAND-MARK:END -->';
  const iB = src.indexOf(begin);
  const iE = src.indexOf(end);
  if (iB === -1 || iE === -1 || iE < iB) {
    console.error(
      `\n${rel} has no ${begin} / ${end} sentinel pair.\n` +
        'Wrap the inline brand mark in those comments so the generator can keep it in sync.',
    );
    process.exit(1);
  }
  const body = inlineMark(product, rootAttrs)
    .split('\n')
    .map((l) => (l.trim() ? indent + l.trim() : l))
    .join('\n');
  const next = `${src.slice(0, iB + begin.length)}\n${body}\n${indent.slice(0, -2)}${src.slice(iE)}`;
  if (next !== src) {
    if (CHECK) drift.push(`${rel} — inlined brand mark differs from the generated markup`);
    else {
      writeFileSync(file, crlf ? next.replace(/\n/g, '\r\n') : next);
      written += 1;
      console.log(`  ${rel} (inline mark)`);
    }
  }
}

// ── 3. Browser extension ────────────────────────────────────────────────────
// The only product still entirely on the retired Verse-Compass mark.

if (want('scc')) {
  console.log(CHECK ? 'checking extension rasters…' : 'writing extension rasters…');
  for (const s of [16, 32, 48]) {
    emit(resolve(ROOT, `browser-extension/icons/icon-${s}.png`), png(compact.scc, s));
  }
  emit(resolve(ROOT, 'browser-extension/icons/icon-128.png'), png(appMark.scc, 128));
}

// ── 4. Data Uploader (Electron) ─────────────────────────────────────────────

if (want('uploader')) {
console.log(CHECK ? 'checking uploader rasters…' : 'writing uploader rasters…');
emit(
  resolve(ROOT, 'data-uploader/build/icon.ico'),
  await pngToIco(ICO_SIZES.map((s) => png(s <= 64 ? compact.uploader : appMark.uploader, s))),
);
emit(resolve(ROOT, 'data-uploader/build/icon.png'), png(appMark.uploader, 256));
emit(resolve(ROOT, 'data-uploader/build/tray.png'), png(tray.uploader, 256));
}

// ── 5. Starscape (Rust) ─────────────────────────────────────────────────────
//
// `gfx.rs` hand-parses the ICO directory to pull a tray-sized entry out, so the
// internal size list matters — keep ICO_SIZES in sync with what it expects.

if (want('starscape')) {
  console.log(CHECK ? 'checking starscape rasters…' : 'writing starscape rasters…');
  emit(
    resolve(ROOT, 'wallpaper-app/assets/starscape.ico'),
    await pngToIco(ICO_SIZES.map((s) => png(s <= 64 ? compact.starscape : appMark.starscape, s))),
  );
  // A SECOND ico for the notification area. `gfx.rs::load_tray_icon` picks the
  // entry nearest 32px, and in the app ico that is the compact tier — a dark
  // #0d2635 disc, which on a dark Windows tray is the invisible icon this whole
  // change exists to fix. The tray tier (bright annulus on transparency) has to
  // be its own file, because the app ico still needs the dark disc for Explorer.
  emit(
    resolve(ROOT, 'wallpaper-app/assets/starscape-tray.ico'),
    await pngToIco([16, 20, 24, 32, 48].map((s) => png(tray.starscape, s))),
  );
}

// ── 6. Family reference sheet ───────────────────────────────────────────────
//
// A rendered contact sheet of every product × tier × size, committed alongside
// the marks. An icon family is judged at the sizes it actually ships at, and a
// reviewer cannot do that from a diff of SVG path data — this is the artifact
// that makes "does the nova still read at 16px?" answerable in a pull request.
// It regenerates with everything else, so it cannot go stale.

if (!ONLY) {
  console.log(CHECK ? 'checking family sheet…' : 'writing family sheet…');
  const img = (buf, x, y, s) =>
    `<image href="data:image/png;base64,${buf.toString('base64')}" x="${x}" y="${y}" width="${s}" height="${s}"/>`;
  const label = (x, y, t, size = 11, fill = '#84a0b6') =>
    `<text x="${x}" y="${y}" fill="${fill}" font-family="Segoe UI, sans-serif" font-size="${size}">${t}</text>`;

  const rows = [
    ['app tier', (p) => [[png(appMark[p], 128), 128]]],
    [
      'compact tier',
      (p) => [48, 32, 24, 16].map((s) => [png(compact[p], s), s]),
    ],
    ['tray tier', (p) => [24, 16].map((s) => [png(tray[p], s), s])],
  ];

  const parts = [
    label(24, 30, 'SC Companion — brand mark family', 16, '#e8ebed'),
    label(24, 50, 'Generated by scripts/build-brand-icons.mjs. Rendered at true pixel size.', 11),
  ];
  let y = 74;
  for (const [name, get] of rows) {
    parts.push(label(24, y + 20, name));
    let x = 150;
    for (const p of PRODUCTS) {
      parts.push(label(x, y + 8, p, 10, '#5a7a94'));
      let xx = x;
      for (const [buf, s] of get(p)) {
        parts.push(img(buf, xx, y + 14, s));
        xx += s + 10;
      }
      x += 250;
    }
    y += rows[0][0] === name ? 160 : 76;
  }

  // The taskbar strips are the point of the whole exercise: this is where a
  // dark disc used to disappear and where the three products must stay apart.
  for (const [bg, caption] of [
    ['#1c1c1c', 'Windows dark taskbar'],
    ['#f3f3f3', 'Windows light taskbar'],
  ]) {
    parts.push(label(24, y + 20, caption));
    parts.push(`<rect x="150" y="${y + 4}" width="560" height="30" fill="${bg}"/>`);
    let x = 164;
    for (const p of PRODUCTS) {
      parts.push(img(png(compact[p], 24), x, y + 7, 24));
      x += 40;
    }
    x += 34;
    for (const p of PRODUCTS) {
      parts.push(img(png(tray[p], 16), x, y + 11, 16));
      x += 30;
    }
    y += 46;
  }

  const H = y + 16;
  const sheet = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 ${H}" width="800" height="${H}">
  <rect width="800" height="${H}" fill="${C.canvas}"/>
  ${parts.join('\n  ')}
</svg>`;
  emit(resolve(BRAND, 'family-sheet.png'), pngBox(sheet, 800, H, C.canvas));
}

// ── Result ──────────────────────────────────────────────────────────────────

if (CHECK) {
  if (drift.length) {
    console.error('\nbrand icons are out of date:\n' + drift.map((d) => `  - ${d}`).join('\n'));
    console.error('\nRun `npm run gen:brand-icons` and commit the result.');
    process.exit(1);
  }
  console.log('\nbrand icons up to date.');
} else {
  console.log(`\nwrote ${written} files.`);
}
